import { spawn } from 'node:child_process';
const p = spawn('/harness-state/.bun/bin/gbrain', ['serve','--surface','starter','--advertise','verbs'], { env: { ...process.env, GBRAIN_HOME: '/harness-state', PATH: '/harness-state/.bun/bin:' + process.env.PATH }, stdio: ['pipe','pipe','pipe'] });
let buf = ''; const pending = new Map(); let id = 0;
p.stdout.on('data', d => { buf += d; let i; while ((i = buf.indexOf('\n')) >= 0) { const line = buf.slice(0, i); buf = buf.slice(i+1); if (!line.trim()) continue; try { const m = JSON.parse(line); if (m.id != null && pending.has(m.id)) { pending.get(m.id)(m); pending.delete(m.id); } } catch {} } });
p.stderr.on('data', d => process.stderr.write('[serve] ' + d));
const rpc = (method, params) => new Promise(r => { const i = ++id; pending.set(i, r); p.stdin.write(JSON.stringify({ jsonrpc: '2.0', id: i, method, params }) + '\n'); });
const call = async (name, args) => { const r = await rpc('tools/call', { name, arguments: args }); return r.result?.content?.map(c => c.text).join('\n') ?? JSON.stringify(r.error); };
const init = await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'openclaw-probe', version: '1' } });
console.log('server:', JSON.stringify(init.result?.serverInfo));
p.stdin.write(JSON.stringify({ jsonrpc: '2.0', method: 'notifications/initialized' }) + '\n');
const tl = await rpc('tools/list', {});
console.log('tools:', tl.result.tools.map(t => t.name).join(', '));
console.log('--- remember via MCP');
console.log((await call('remember', { fact: 'GBrain MCP round-trip note: verified over stdio with codeword violet-harbor', provenance: 'install-check-mcp', content_origin: 'agent_inferred' })).slice(0, 600));
console.log('--- recall via MCP');
console.log((await call('recall', { query: 'violet-harbor' })).slice(0, 1200));
console.log('--- recall install marker via MCP');
console.log((await call('recall', { query: 'gbrain install check' })).slice(0, 1200));
p.kill(); process.exit(0);

